import sys,os
sys.path.append(os.path.abspath(os.path.dirname(__file__) + '/' + '..'))


import math
from typing import Dict, Any, List
from elasticsearch import Elasticsearch, exceptions
from pprint import pprint
from config.config import AI_HOST, AI_USERNAME, AI_PASSWORD, AI_PORT
from util.time_util import calculate_execution_time

class ElasticSearchClient:
    """Class to interact with Elasticsearch to retrieve and process data.

    This class provides methods to perform Elasticsearch operations, including querying,
    calculating custom scores, and fetching top words based on the match query.

    Attributes:
        es (Elasticsearch): Elasticsearch client instance.
        index (str): The index to search in.
    """

    def __init__(self, host: str, username: str, password: str, port: int, index: str):
        """Initializes the Elasticsearch client and checks if the connection is successful.

        Args:
            host (str): Elasticsearch host.
            username (str): Elasticsearch username for authentication.
            password (str): Elasticsearch password for authentication.
            port (int): Port number for Elasticsearch.
            index (str): The index in Elasticsearch to query.
        """
        try:
            self.es = Elasticsearch(
                hosts=host,
                http_auth=(username, password),
                port=port
            )
            self.index = index
            # Ping to check if the connection is successful
            if not self.es.ping():
                raise ConnectionError("Failed to connect to Elasticsearch!")
            print("Successfully connected to Elasticsearch!")
        except exceptions.ElasticsearchException as e:
            print(f"Error initializing Elasticsearch client: {e}")
            raise  # Re-raise the exception after logging

    def search_knowledge(self, knowledge_base_id: str) -> List[Dict[str, Any]]:
        query_body = {
            "query": {
                "bool": {
                    "must": [
                        {
                            "match": {
                                "knowledgeBaseId": knowledge_base_id
                            }
                        }
                    ]
                }
            }
        }
        response = self.es.search(index=self.index, body=query_body)
        return response['hits']['hits']
